<?php
require 'config/database.php'; require 'includes/auth.php'; require_once 'includes/media.php';
$posts = $pdo->query("SELECT p.*, (SELECT COUNT(*) FROM blog_comments c WHERE c.post_id=p.id AND c.status='visible') comments_count,
 (SELECT COUNT(*) FROM blog_likes l WHERE l.post_id=p.id) likes_count
 FROM blog_posts p WHERE p.status='published' ORDER BY p.published_at DESC, p.id DESC")->fetchAll();
?>
